) AS (
  VALUES 
    (1161::BIGINT, 'El profe hace que el curso se pase solo, no deja trabajos para luego de clase ni exige demasiado para las obras. Deja que las obras sean a imaginación de los estudiantes, definitivamente llevaría el curso con el de nuevo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, '115f6e1eac258b03de8ce3cb6433b0600c18dc2ea3d9e55cd0d906374b038530'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Es divertido, no me cuadraba la idea de actuar y pense que iba a ser una tontera el curso pero termino siendo un ambiente agradable y vacilon. No deja bretes ni nada para fuera de la clase 1 hora a la semana para ir a la clase y ya paso el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '907794aba8d3441a904472db1eeb94fe834e5069c66705bc121982592c9fb2d5'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Demasiado bueno, super atento, gracioso. La clase es como ir a jugar. Matriculen con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'b13b13ecebbc91a9bb83e900a9c44c987d1785cfdcdc571a3d3b61ec7306c6a7'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Es buen profesor y persona, aunque siento que el curso en virtual puede requerir más tiempo de lo que debería . Las bitácoras son sumamente sencillas, pero hay que ponerle cuidado a los informes y a las obras, ya que califica detalladamente.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'bea734f4e17cd2b3ed190ad8a7c9cfa2836aaf18dcf725dcad8a05d1f7d2d77a'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Un bonito curso, sirve para desestresarse y olvidarse de la carga del TEC por un par de horas, aunque puede llegar a necesitar MUCHÍSIMAS horas extraclase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '28288ce4935de23cece19dede05d8c85b117607d9092abd92be85bca1cf39be8'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'El profe es super bueno, las clases son muy divertidas y todas las tareas son muy entretenidas, si quiere pasar facil tal vez este no sea su curso, pero si quiere aprender y divertirse no se va a arrepentir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'f7664157cff5d241a30c5f3837a1c8c324015b5587d904ca6928cbb2b991eedd'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Un profe excelente, recomendadísimo. Se adapto muy bien a la virtualidad. Presencial las clases eran todavía mejores, las hacía super divertidas. Y siempre esta de buen humor. Genial ese profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '27c651ab2b698974554bafcf9aaa3bd7299f3508ee5a10435282b373ebf78b61'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Excelente persona, muy amable y es fácil de pasar el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-03T00:00:00+00:00'::TIMESTAMPTZ, '007ad526ee2c4e47d6903e21fea16e18de651b37e6c794b53aa956d60a320c58'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Las clases son entretenidas, él se empeña en que le ayuden al estudiante a despejarse un rato del resto de cursos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '0c9e9f35acb4a354616caf20803f13aae57b38e52ccbd51158127da4bf4d1ca1'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Excelente profesor las clases súper dinámicas e interesantes en cada una se aprende algo nuevo, inspira tranquilidad y transmite la pasión por el arte. Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-14T00:00:00+00:00'::TIMESTAMPTZ, '242ac3c597fd2a4a30244ab45e4efdeb5f056ae36f8227bf9885e0d28bea1af7'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Hace las clases entretenidas, cumple con los objetivos del curso. Inspira creatividad en los estudiantes. Las clases son un relajante del mundo TEC. Protti es una excelente persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, '9422c155c87b6f96d750f92a0c2b73c0964814373716e739966aee1157814e92'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Cumple con el objetivo del curso, enseñar algo totalmente nuevo de una forma divertida y además ayuda a liberar el estrés del semestre. Muy buena persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '85f485331e7a60d340d0641e7072a8f712d631c4f073bb8a04c0b62f6193e30e'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Super divertido'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ad4d01d7b7f7d68ce73a3dfa7ee0ba331d2b8760a11c50e1a90a5e2978173bbd'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Si fuese posible llevaria este curso todos mis semestres, es de lo más desestresante. En la obra que hay que presentar al final gracias a su ayuda fuimos uno de los mejores grupos, la verdad lo recomiendo demasiado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '60cedb715c088a93ea6b6dcfb3f92e7fb5486978d22d3af90f912322d1561cd2'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'f2c4d40c53b98aa0c00646c41b8135044627f5c425d721f74622d36a25196a47'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Las dinámicas que propone en clase son muy divertidas, se aprende mucho de teatro en su clase. Los trabajos que deja no quitan mucho tiempo porque los reportes son sencillos. Se esfuerza mucho para que la obra final salga impecable. Lo recomiendo mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '7e49f15c993b299fdff720829d00293fc28aafdac525c9d983e285a770e89438'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2018-03-24T00:00:00+00:00'::TIMESTAMPTZ, '51b0a12e37621c97199e5483ee2c27b8556e89b2c90b2aa2ec4a517ff9fd916d'::TEXT, ARRAY[504]::BIGINT[]),
    (1161::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'cec33b8dbba312d153e76b7584d4905c6a753338b894233029c1e7792c7db9d5'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'excelente profe! super recomendado le interesa mucho saber si los estudiantes se sienten comodos con la metodologia de la clase y como puede mejorar!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'b88226b49dc3d081ab66c9fef6b932fe027e1592031517417c099f530baa2688'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Excelente profesor, planea cada clase adaptándose al grupo y a las observaciones que los estudiantes hagan. Busca que cada quien se divierta y aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'bda6da898907ee243d7ddafefad0619878b16df2e1e41663a26bb661bef9ac2d'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Muy buen profesor, no es pesado lo contrario las clases son muy divertidas y ayuda a relajarse. Con solo ir a clases, hacer reportes de obras y la presentación final pasa fácil. No es pesado, sólo es participar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd901316b722b1b2fe364f32dd23f323eede8c6c42cb9e2407c170a06bf5d826a'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Super buen profe y la clase es excelente para desestresarse de lo pesado del semestre. Lo malo es que para la obra final no acepta sugerencias'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, '509ed2c9d3469418fb5c88978df79b00aae8dfb582328feb33aac21eb2ea8cc5'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'La clase es el desestrés de la semana, es la mejor cultural que pueden llevar, si pueden meter teatro con el MATRICULELO!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2b693a57c04c18413d3269aa10b866c4d7cbee13e6d3b308ba6c45cf8e3c5deb'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Es de esos profesores con los que uno capta fácilmente lo que se busca hacer. Es una persona bastante entretenida y centrada en lo que hace. Inspira bastante confianza en los estudiantes y se percibe fácilmente el apoyo que les da. Lo recomiendo totalmente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '6bf65006aa4b429022eff82ad2659258e67918387a01e639600d628916a8e416'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-20T00:00:00+00:00'::TIMESTAMPTZ, '663ea72e01d097d34f701e46a4002fb3aaa017f8a175600e84dc65604fcd0907'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'No es estricto y se ve que disfruta de dar clases. Es un curso muy bonito 100% recomendado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2016-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'd40c67670e7a9d650fea23a5192c7b608eda086f4d73ec8c5e250c42ca2df3b3'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Un muy buen profesor. No lo va a explotar en el curso (como otros profes), al contrario, es bastante relajado y hace que se disfrute el rato.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '1c2d9327ddeddea426d2121904d9109ea5fec0cb4bf1da22cdb7752140d3ceec'::TEXT, ARRAY[692]::BIGINT[]),
    (1161::BIGINT, 'Es el mejor profesor de teatro, los demás son muy estrictos pero él no. Hace las clases muy entretenidas y sabe motivara sus alumnos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '021d4c6fca1c87840bf16f6758536612923d7b21c4fc4cb85e2b54a1ba6fc003'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'El curso con él es muuuuy fácil. Las clases son divertidas si el grupo aporta. El profe en sí, no es tan divertido.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'c8c14f63a62112037695ffba807fde269d2c52c10facbf30c34c0bd8e653acd4'::TEXT, ARRAY[498]::BIGINT[]),
    (1161::BIGINT, 'Facil de pasar, las clases son entretenidas porque se hace mucho feo. Pero en general el profe no es muy divertido. Se hacen actividades de calentamiento que son muy bonitas. Una buena opcion para ganar una cultural facilmente. (Hay mejores profes de Teatro)'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'cae4f585d903333bc5283805e038d38ced144efa9a7250e37ce47e523bcb12a9'::TEXT, ARRAY[498]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
